use verus::prelude::*;

// Each inspector covers exactly (2*d + 1) blocks,
// so the minimal number is ceil(n / (2*d+1)).

#[requires(n >= 0)]
#[requires(d >= 0)]
// postcondition: if we let coverage = 2*d + 1, then
//    result == ceil(n / coverage)
// equivalently,
//    result * coverage >= n    AND
//    (result == 0 || (result - 1) * coverage < n)
#[ensures({
    let coverage = 2*d + 1;
    result * coverage >= n
    && (result == 0 || (result - 1) * coverage < n)
})]
fn min_inspectors(n: i8, d: i8) -> i8 {
    // Each inspector can cover a block of length 2*d + 1.
    let coverage = 2 * d + 1;
    // We need ceil(n / coverage).  For non-negative integers this is:
    //    (n + coverage - 1) / coverage
    (n + coverage - 1) / coverage
}

